// src/pages/port-svg.ts
function portSvg(sz) {
  const w = sz, h = Math.round(sz * 1.1);
  const rx2 = Math.max(2, Math.round(sz * 0.09));
  const sox = Math.round(w * 0.15);
  const sow = w - sox * 2;
  const soy = Math.round(h * 0.22);
  const soh = Math.round(h * 0.58);
  const pinW = Math.max(1, Math.round(sow / 10));
  const pinH = Math.max(3, Math.round(h * 0.16));
  const pinY = soy + soh - pinH;
  const pinGap = (sow - 8 * pinW) / 9;
  const ledR = Math.max(2, Math.round(sz * 0.07));
  const ledX = w - Math.round(sz * 0.14);
  const ledY = Math.round(sz * 0.11);
  let pins = "";
  for (let p = 0; p < 8; p++) {
    const px = sox + pinGap + p * (pinW + pinGap);
    pins += '<rect x="' + px.toFixed(1) + '" y="' + pinY + '" width="' + pinW + '" height="' + pinH + '" rx="0.5" style="fill:' + paletteCss("--text-main", 0.35) + '"/>';
  }
  return '<svg class="if-port-svg" width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + " " + h + '" xmlns="http://www.w3.org/2000/svg"><rect class="port-body" x="0.5" y="0.5" width="' + (w - 1) + '" height="' + (h - 1) + '" rx="' + rx2 + '" stroke-width="1.5" fill-opacity="1"/><rect x="' + sox + '" y="' + soy + '" width="' + sow + '" height="' + soh + '" rx="2" style="fill:' + paletteCss("--bg-deep", 0.5) + ";stroke:" + paletteCss("--border", 0.2) + '" stroke-width="0.8"/>' + pins + '<circle class="port-led" cx="' + ledX + '" cy="' + ledY + '" r="' + ledR + '"/></svg>';
}

