      if (q && !(r.srcIp.toLowerCase().includes(q) || r.dstIp.toLowerCase().includes(q) || (r.name || "").toLowerCase().includes(q) || (r.mac || "").toLowerCase().includes(q) || (r.org || "").toLowerCase().includes(q))) return false;
      if (iface2 && r.iface !== iface2) return false;
