// src/diffview.ts
function hunksHTML(hunks) {
  return hunks.map((h) => {
    const head = '<div class="bk-hunk-hdr">@@ -' + h.aStart + "," + h.aCount + " +" + h.bStart + "," + h.bCount + " @@</div>";
    return head + h.lines.map((l) => {
      const cls = l.op === "+" ? "bk-add" : l.op === "-" ? "bk-del" : "";
      const num2 = l.op === "+" ? l.bLine : l.aLine;
      return '<div class="bk-line ' + cls + '"><span class="bk-ln">' + (num2 || "") + "</span>" + esc(l.op + " " + l.text) + "</div>";
    }).join("");
  }).join("");
}

