  rows.innerHTML = r.flows.map((f) => "<tr><td>" + protoPill(f.protocol) + "</td><td>" + end(f.srcAddress, f.srcPort) + "</td><td>" + end(f.dstAddress, f.dstPort) + '</td><td style="color:var(--accent-rx)">' + bps(f.rxBps) + '</td><td style="color:var(--accent-tx)">' + bps(f.txBps) + "</td></tr>").join("");
