    return '<div class="cfg-hist-target"><div class="cfg-prev-head"><strong>' + esc(t.label) + "</strong>" + pill2(TARGET_STATE, t.state) + (facts.length ? '<span class="cfg-meta">' + esc(facts.join(" \xB7 ")) + "</span>" : "") + "</div>" + (t.error ? '<div class="cfg-banner is-bad">' + esc(t.error) + "</div>" : "") + (t.warning ? '<div class="cfg-banner is-warn">' + esc(t.warning) + "</div>" : "") + output("The syntax check, in RouterOS's words", t.dryRunOutput, null) + output("The import, in RouterOS's words", t.importOutput, t.failedLine) + "</div>";
