function batchRows(batches, now) {
  if (!batches.length) return '<tr><td colspan="4" class="ztp-help">No generic scripts yet.</td></tr>';
  return batches.map((b) => "<tr><td>" + esc(b.name) + "</td><td>" + (b.revokedAt ? pill("Revoked", "muted") : b.live ? pill("Live", "tx") + ' <span class="ztp-help">expires ' + esc(relTime(b.expiresAt, now)) + "</span>" : pill("Expired", "muted")) + "</td><td>" + b.devices + "</td><td>" + (b.live ? '<button class="sbtn sbtn-danger ztp-btn" type="button" data-ztp-revoke="' + esc(b.id) + '">Revoke</button>' : "") + "</td></tr>").join("");
}

