async function act(action, d) {
  const name = d.label || d.identity || d.serial || "this device";
  const base2 = "/api/ztp/devices/" + encodeURIComponent(d.id);
  message = "";
  try {
    switch (action) {
      case "onboard":
        openOnboard(d);
        return;
      case "reject":
        if (!confirm("Reject " + name + "?\n\nIts tunnel is closed and it can no longer reach this MikroDash.")) return;
        await api2("POST", base2 + "/reject");
        return;
      case "retry":
        await api2("POST", base2 + "/retry");
        return;
      case "delete":
        if (!confirm("Remove " + name + " from provisioning?" + (d.state === "awaiting" ? "\n\nIts script stops working." : ""))) return;
        await api2("DELETE", base2);
        return;
      case "regenerate": {
        if (!confirm("Make a new script for " + name + "?\n\nThe old one stops working.")) return;
        const r = await api2("POST", base2 + "/regenerate", {});
        showScript("New script for " + name, r, "Run it on " + name + ".");
        return;
      }
    }
  } catch (e) {
    message = errText(e);
    renderSection();
  }
}
function renderSettings(p) {
  const s = p.status;
  const status = el("ztpStatusLine");
  if (status) status.innerHTML = statusLine(s);
  const inst = el("ztpInstanceId");
  if (inst) inst.textContent = s.instanceId || "Made when provisioning is first switched on";
  const key = el("ztpPublicKey");
  if (key) key.textContent = s.publicKey || "-";
  const body3 = el("ztpBatchBody");
  if (body3) body3.innerHTML = batchRows(p.batches, Date.now());
  const lan = el("s_ztpLanUrl");
  const suggest = lanSuggestion(location.origin, location.hostname);
  if (lan && suggest) lan.placeholder = suggest;
}
function mountSettings() {
  el("ztpBatchBtn")?.addEventListener("click", () => {
    const nameIn = el("ztpBatchName");
    const days = Number(el("ztpBatchDays")?.value) || 7;
    const name = nameIn?.value.trim() ?? "";
    const msg = el("ztpBatchMsg");
    if (msg) msg.textContent = "";
    if (!name) {
      if (msg) msg.textContent = "Name the script first, for example the rollout it is for.";
      return;
    }
    void api2("POST", "/api/ztp/batches", { name, days }).then((r) => {
      if (nameIn) nameIn.value = "";
      showScript("Generic script: " + name, r, "Run it on any number of routers; each waits on the Devices page to be onboarded.");
    }, (e) => {
      if (msg) msg.textContent = errText(e);
    });
  });
  el("ztpBatchBody")?.addEventListener("click", (e) => {
    const b = e.target.closest?.("[data-ztp-revoke]");
    if (!b) return;
    if (!confirm("Revoke this generic script?\n\nRouters that have not called home yet can no longer use it. Devices it already brought in are not affected.")) return;
    void api2("POST", "/api/ztp/batches/" + encodeURIComponent(b.dataset.ztpRevoke ?? "") + "/revoke").catch((err) => {
      const m = el("ztpBatchMsg");
      if (m) m.textContent = errText(err);
    });
  });
}
function renderNotice(p) {
  const n = el("ztpNotice");
  if (!n) return;
  const pending4 = p.devices.filter((d) => d.state === "pending").length;
  n.hidden = !pending4;
  const text2 = el("ztpNoticeText");
  if (text2) text2.textContent = pending4 + (pending4 === 1 ? " device has" : " devices have") + " called home and " + (pending4 === 1 ? "is" : "are") + " waiting to be onboarded.";
}
function mountZtp(socket) {
  socket.on("ztp:state", (p) => setZtpState(p));
  socket.on("connect", () => socket.emit("ztp:watch", {}));
  if (socket.isOpen()) socket.emit("ztp:watch", {});
  onZtpState((p) => {
    renderSection();
    renderSettings(p);
    renderNotice(p);
  });
  setInterval(renderSection, 6e4);
  el("ztpAddBtn")?.addEventListener("click", openAddDevice);
  el("ztpSection")?.addEventListener("click", (e) => {
    const b = e.target.closest?.("[data-ztp-act]");
    const d = b && ztpState()?.devices.find((x) => x.id === b.dataset.ztpId);
    if (b && d) void act(b.dataset.ztpAct ?? "", d);
  });
  el("ztpNoticeBtn")?.addEventListener("click", () => {
    document.querySelector('.nav-item[data-page="devices"]')?.click();
  });
  mountSettings();
}

