  const tbody = el("rptBwTbody");
  if (tbody) {
    tbody.innerHTML = slice.length ? slice.map((r) => '<tr><td style="color:var(--text-muted)">' + esc(fmtTs(r.ts)) + "</td><td>" + esc(r.interface || "") + '</td><td style="text-align:right;color:var(--accent-rx)">' + esc(fmtDataMB(+r.rx_mb)) + '</td><td style="text-align:right;color:var(--accent-tx)">' + esc(fmtDataMB(+r.tx_mb)) + "</td></tr>").join("") : '<tr><td colspan="4" class="tbl-empty">No data for this range.</td></tr>';
  }
