      const ack = r.acknowledged_at ? esc(fmtTs(r.acknowledged_at)) + (r.acknowledged_by ? " \xB7 " + esc(r.acknowledged_by) : "") : r.resolved_at ? "-" : '<button class="sbtn sbtn-ghost is-sm" data-ack-id="' + esc(String(r.id)) + '">Acknowledge</button>';
      return '<tr><td style="color:var(--text-muted)">' + esc(fmtTs(r.fired_at)) + "</td><td>" + esc(r.alert_label || r.alert_type || "") + '</td><td style="color:var(--text-muted)">' + esc(r.subject || "-") + '</td><td style="max-width:260px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(r.detail || "-") + "</td><td>" + res + '</td><td style="color:var(--text-muted)">' + ack + '</td><td style="text-align:right">' + esc(dt) + "</td></tr>";
