    secs.innerHTML = state.sections.map((sec) => '<label><input type="checkbox" data-rs-sec="' + esc(sec) + '"' + (chosen.indexOf(sec) !== -1 ? " checked" : "") + ">" + esc(sec) + "</label>").join("");
