    name: el("rs_name")?.value ?? "",
    frequency: el("rs_frequency")?.value ?? "",
    sendHour: Number(el("rs_hour")?.value ?? "0"),
    sections: chosenSections(),
    iface: el("rs_iface")?.value ?? "",
