// src/pages/setup-overlay.ts
function collectSetupBody(f) {
  return {
    label: f.label || "",
    host: f.host || "",
    port: parseInt(f.port || "8729", 10),
    username: f.username || "admin",
    password: f.password || "",
    defaultIf: f.defaultIf || "ether1",
    pingTarget: f.pingTarget || "1.1.1.1",
    tls: !!f.tls,
    tlsInsecure: !!f.tlsInsecure
  };
}
function flipPortForTls(current4, tlsChecked) {
  const p = parseInt(current4, 10);
  if (tlsChecked && p === 8728) return "8729";
  if (!tlsChecked && p === 8729) return "8728";
  return null;
}
var SETUP_WATCH_FIELDS = [
  "setupHost",
  "setupPort",
  "setupUser",
  "setupPass",
  "setupTls",
  "setupTlsInsecure"
];
function setupTestResultText(ok, boardName, error) {
  if (ok) return "\u2713 Connected" + (boardName ? " - " + boardName : "");
  return "\u2717 " + (error || "Failed");
}

// src/pages/setup-overlay-wire.ts
var testPassed = false;
function setSaveReady(ready2) {
  testPassed = ready2;
  const save4 = el("setupSaveBtn");
  if (!save4) return;
  save4.disabled = !ready2;
  save4.style.opacity = ready2 ? "" : "0.45";
  save4.title = ready2 ? "" : 'Run "Test Connection" successfully before saving';
}
function showErr(msg) {
  const box = el("setupError");
  if (!box) return;
  box.textContent = msg;
  box.style.display = "block";
}
function clearErr() {
  const box = el("setupError");
  if (box) box.style.display = "none";
}
function showOverlay() {
  const ov = el("setupOverlay");
  if (!ov) return;
  ov.style.display = "block";
  document.body.classList.add("is-disconnected");
  globalThis._rosCurrentlyDisconnected = true;
  const svg3 = el("netDiagram");
  if (svg3 && typeof svg3.pauseAnimations === "function") svg3.pauseAnimations();
  setSaveReady(false);
}
function hideOverlay() {
  const ov = el("setupOverlay");
  if (!ov) return;
  ov.style.display = "none";
  document.body.classList.remove("is-disconnected");
}
function body2() {
  const v2 = (id) => el(id)?.value ?? "";
  const c = (id) => !!el(id)?.checked;
  return collectSetupBody({
    label: v2("setupLabel"),
    host: v2("setupHost"),
    port: v2("setupPort"),
    username: v2("setupUser"),
    password: v2("setupPass"),
    defaultIf: v2("setupIf"),
    pingTarget: v2("setupPing"),
    tls: c("setupTls"),
    tlsInsecure: c("setupTlsInsecure")
  });
}
function setBusy2(busy) {
  const test2 = el("setupTestBtn");
  const save4 = el("setupSaveBtn");
  if (test2) test2.disabled = busy;
  if (save4) {
    save4.disabled = busy || !testPassed;
    save4.textContent = busy ? "Connecting\u2026" : "Connect";
  }
}
function showSetupOverlayNow() {
  if (!el("setupOverlay")) return;
  showOverlay();
}
function initSetupOverlay(socket) {
  const ov = el("setupOverlay");
  if (!ov) return;
  socket.on("setup:required", showOverlay);
  for (const id of SETUP_WATCH_FIELDS) {
    const field = el(id);
    if (!field) continue;
    const evt = field.type === "checkbox" ? "change" : "input";
    field.addEventListener(evt, () => {
      if (!testPassed) return;
      setSaveReady(false);
      const res = el("setupTestResult");
      if (res) res.textContent = "";
    });
  }
  const tls = el("setupTls");
  const port = el("setupPort");
  if (tls && port) {
    tls.addEventListener("change", () => {
      const next = flipPortForTls(port.value, tls.checked);
      if (next !== null) port.value = next;
    });
  }
  el("setupTestBtn")?.addEventListener("click", () => {
    clearErr();
    setSaveReady(false);
    const res = el("setupTestResult");
    if (res) {
      res.textContent = "Testing\u2026";
      res.style.color = "";
    }
    const test2 = el("setupTestBtn");
    if (test2) test2.disabled = true;
    const b = body2();
    if (!b.host) {
      showErr("Host is required");
      if (test2) test2.disabled = false;
      return;
    }
    void fetch("/api/routers/test", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(b)
    }).then((r) => r.json()).then((d) => {
      if (test2) test2.disabled = false;
      if (res) {
        res.textContent = setupTestResultText(!!d.ok, d.boardName || "", d.error || "");
        res.style.color = d.ok ? "var(--accent-ok)" : "var(--accent-err)";
      }
      setSaveReady(!!d.ok);
    }).catch(() => {
      if (test2) test2.disabled = false;
      if (res) {
        res.textContent = "\u2717 Request failed - check browser console";
        res.style.color = "var(--accent-err)";
      }
      setSaveReady(false);
    });
  });
  el("setupSaveBtn")?.addEventListener("click", () => {
    if (!testPassed) return;
    clearErr();
    const b = body2();
    if (!b.host) {
      showErr("Host is required");
      return;
    }
    setBusy2(true);
    void fetch("/api/routers", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify(b)
    }).then((r) => r.json()).then((d) => {
      if (!d.ok) throw new Error(d.error || "Failed to add router");
      const id = d.router && d.router.id;
      if (!id) throw new Error("No router ID returned");
      return fetch("/api/routers/" + encodeURIComponent(id) + "/activate", {
        method: "POST",
        credentials: "same-origin"
      }).then((r) => r.json());
    }).then((d) => {
      if (!d.ok && !d.switching) throw new Error(d.error || "Failed to activate router");
      hideOverlay();
      setBusy2(false);
    }).catch((e) => {
      showErr(e && e.message || "Unexpected error");
      setBusy2(false);
    });
  });
  setSaveReady(false);
}

