  const head = '<div class="dvm-sec-head"><h3>Ports</h3>' + (live2 && live2.portsRead && live2.ports.length ? pill(up2 + " of " + live2.ports.length + " up", "muted") : "") + (live2 && live2.leases != null ? pill(live2.leases + " client" + (live2.leases === 1 ? "" : "s"), "muted") : "") + "</div>";
