  chart6.data.datasets[0].data = pts.map((p) => ({ x: p.ts, y: p.rx_mbps }));
  chart6.data.datasets[1].data = pts.map((p) => ({ x: p.ts, y: p.tx_mbps }));
  let max = 0;
  for (const p of pts) max = Math.max(max, p.rx_mbps, p.tx_mbps);
  yCurrent = max || 1;
  chart6.options.scales.y.max = yCurrent;
  rbCurrent3 = rb;
  const win = axisWindow(anchorMs(lastSampleTs3, serverOffset3, Date.now(), pts), WAN_WINDOW_SECS, rb);
  chart6.options.scales.x.min = win.min;
