// src/pages/dashboard-talkers.ts
function renderTalkers(data) {
  const table = el("talkersTable");
  if (!table) return;
  const devices = data.devices || [];
  if (!devices.length) {
    table.innerHTML = '<tr><td colspan="4" class="empty-state">' + (data.available === false ? "Kid Control is not available on this router" : "No devices") + "</td></tr>";
    return;
  }
  table.innerHTML = devices.map((d) => "<tr><td>" + esc(d.name || "-") + '</td><td style="color:var(--text-muted)">' + esc(d.mac || "-") + '</td><td class="text-end" style="color:var(--accent-rx)">' + fmtMbps(d.rx_mbps) + '</td><td class="text-end" style="color:var(--accent-tx)">' + fmtMbps(d.tx_mbps) + "</td></tr>").join("");
}

// src/pages/dashboard-netwatch.ts
function renderNetwatch(data) {
  const tbody = el("netwatchTable");
  if (!tbody) return;
  const hosts = data.hosts || [];
  if (!hosts.length) {
    tbody.innerHTML = '<tr><td colspan="3" class="empty-state">No hosts configured</td></tr>';
    return;
  }
  tbody.innerHTML = hosts.map((h) => {
    const isUp = h.status === "up";
    const isDown = h.status === "down";
    const statusHtml = isUp ? '<span class="pill pill-ok pill-dot">Up</span>' : isDown ? '<span class="pill pill-err pill-dot">Down</span>' : '<span style="color:var(--text-muted);font-size:.7rem">' + esc(h.status || "?") + "</span>";
    return "<tr><td>" + statusHtml + '</td><td style="font-weight:600">' + esc(h.name || "-") + '</td><td style="color:var(--text-muted)">' + esc(h.host || "-") + "</td></tr>";
  }).join("");
}

// src/pages/dashboard-vpn.ts
function parseDurationSec(s) {
  if (!s || s === "never") return Infinity;
  let total = 0;
  const re = /(\d+)([wdhms])/g;
  let m;
  while ((m = re.exec(s)) !== null) {
    const n = parseInt(m[1], 10);
    if (m[2] === "w") total += n * 604800;
    else if (m[2] === "d") total += n * 86400;
    else if (m[2] === "h") total += n * 3600;
    else if (m[2] === "m") total += n * 60;
    else total += n;
  }
  return total || Infinity;
}
function renderVpnCard(data) {
  const table = el("vpnTable");
  if (!table) return;
  const wgPeers = (data.tunnels || []).filter((t) => t.type === "WireGuard");
  const connected = wgPeers.filter((t) => t.state === "active");
  connected.sort((a, b) => parseDurationSec(a.lastHandshake) - parseDurationSec(b.lastHandshake));
  if (!connected.length) {
    table.innerHTML = '<tr><td colspan="3" class="empty-state">No active peers</td></tr>';
    return;
  }
  table.innerHTML = connected.slice(0, getVpnDashTopN()).map((t) => {
    const endStr = t.endpoint ? '<div style="font-size:.65rem;color:var(--text-muted);margin-top:.1rem">' + esc(t.endpoint) + "</div>" : "";
    return '<tr><td><span class="pill pill-ok pill-dot">Up</span></td><td><div style="font-size:.78rem;font-weight:600">' + esc(t.name || t.interface || "-") + "</div>" + endStr + '</td><td style="color:var(--text-muted)">' + esc(t.lastHandshake || "-") + "</td></tr>";
  }).join("");
}

