      const t = e.topics.toLowerCase();
      if (t.indexOf("dhcp") >= 0) cls += " log-dhcp";
      else if (t.indexOf("wireless") >= 0) cls += " log-wireless";
      else if (t.indexOf("firewall") >= 0) cls += " log-firewall";
      else if (t.indexOf("system") >= 0) cls += " log-system";
