var STREAM_WARN_CARDS = {
  traffic: "trafficCard",
  connections: "connCard"
};
function renderStreamHealth(h) {
  if (!h) return;
  const cardId = STREAM_WARN_CARDS[h.collector];
  if (!cardId) return;
  const card2 = el(cardId);
  const warn = el(cardId + "Warn");
  if (!card2 || !warn) return;
  if (h.degraded) {
    warn.textContent = "\u26A0 Data incomplete - stream restarted " + h.restarts + " times without recovering";
    card2.classList.add("is-degraded");
  } else {
    warn.textContent = "";
    card2.classList.remove("is-degraded");
  }
}
function renderWanStatus(s) {
  const badge = el("wanStatusBadge");
  if (!badge) return;
  badge.className = "pill pill-dot";
  if (s.disabled) {
    badge.className += " pill-muted";
    badge.textContent = (s.ifName || "?") + " \xB7 disabled";
  } else if (s.running) {
    badge.className += " pill-ok";
    badge.textContent = (s.ifName || "?") + " \xB7 up";
  } else {
    badge.className += " pill-err";
    badge.textContent = (s.ifName || "?") + " \xB7 down";
  }
}

