// src/iptip.ts
function initIpTip() {
  const tip = document.createElement("div");
  tip.className = "ip-tip";
  document.body.appendChild(tip);
  function showTip(target, e) {
    const ip = target.dataset.ip || "", org = target.dataset.org || "", cat = target.dataset.cat || "";
    if (!ip) {
      tip.style.display = "none";
      return;
    }
    tip.innerHTML = esc(ip) + (org ? '<span class="ip-tip-org">' + esc(org) + '</span><span class="ip-tip-cat pill pill-' + (SVC_TONE[cat || "other"] || "muted") + '">' + esc(cat) + "</span>" : "");
    tip.style.transform = "translate(" + (e.clientX + 14) + "px," + (e.clientY - 32) + "px)";
    tip.style.display = "block";
  }
  document.addEventListener("mouseover", (e) => {
    const t = e.target;
    const target = t && t.closest ? t.closest(".has-ip-tip") : null;
    if (target) showTip(target, e);
    else tip.style.display = "none";
  });
  document.addEventListener("mousemove", (e) => {
    if (tip.style.display === "none") return;
    tip.style.transform = "translate(" + (e.clientX + 14) + "px," + (e.clientY - 32) + "px)";
  });
  document.addEventListener("mouseleave", () => {
    tip.style.display = "none";
  }, true);
}

