// src/pages/dashboard-grid-store.ts
function loadLayout() {
  try {
    const raw = localStorage.getItem(LS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && Array.isArray(parsed.cards) && parsed.cards.length > 0) {
        return mergeLayout(parsed.cards);
      }
    }
  } catch {
  }
  return cloneLayout(DEFAULT_LAYOUT);
}
function saveLayout(layout3) {
  localStorage.setItem(LS_KEY, JSON.stringify({ cards: layout3 }));
  void fetch("/api/dashboard-layout", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    credentials: "same-origin",
    body: JSON.stringify({ cards: layout3 })
  }).then((r) => {
    if (!r.ok) console.warn("[MikroDash] dashboard layout save failed - HTTP", r.status);
    else console.log("[MikroDash] dashboard layout saved to server");
  }).catch((e) => {
    console.warn("[MikroDash] dashboard layout save error:", e);
  });
}
function applyLayout(l) {
  const root2 = el("dash-grid-root");
  if (root2) {
    const rows = gridRows(l);
    root2.style.gridTemplateRows = rows > ROWS ? "repeat(" + rows + ", minmax(40px, 1fr))" : "";
  }
  for (const c of l) {
    const node = el(c.id);
    if (!node) continue;
    if (!c.visible) {
      node.style.display = "none";
      continue;
    }
    node.style.display = "";
    node.style.gridColumn = c.x + " / span " + c.w;
    node.style.gridRow = c.y + " / span " + c.h;
  }
}
function notifyRoom(eventName, room) {
  document.dispatchEvent(new CustomEvent(eventName, { detail: room }));
}
function syncDashRooms(layout3, focused, rooms = CARD_ROOMS) {
  const sent = {};
  for (const c of layout3) {
    if (!c.visible) continue;
    const room = rooms[c.id];
    if (!room || sent[room]) continue;
    sent[room] = true;
    notifyRoom(focused ? "dashcard:room:focus" : "dashcard:room:blur", room);
  }
}
async function mergeLayoutFromServer() {
  try {
    const r = await fetch("/api/dashboard-layout");
    const data = await r.json();
    if (!data || !Array.isArray(data.cards) || !data.cards.length) return null;
    const merged = mergeLayout(data.cards);
    localStorage.setItem(LS_KEY, JSON.stringify({ cards: merged }));
    return merged;
  } catch {
    return null;
  }
}

// src/pages/dashboard-grid-edit.ts
function dashActive() {
  const p = el("page-dashboard");
  return !!p && p.classList.contains("active");
}
function notifyRoom2(eventName, room) {
  document.dispatchEvent(new CustomEvent(eventName, { detail: room }));
}
function createGridEditor(initial, rooms = CARD_ROOMS) {
  let layout3 = initial;
  let editSnapshot = [];
  let editing4 = false;
  const getCard = (id) => layout3.find((c) => c.id === id);
  function updateGridOverlay() {
    const root2 = el("dash-grid-root");
    if (!root2) return;
    const r = root2.getBoundingClientRect();
    const sz = getCellSize(r.width, r.height, gridRows(layout3));
    root2.style.setProperty("--grid-cell-w", sz.colW + GAP2 + "px");
    root2.style.setProperty("--grid-cell-h", sz.rowH + GAP2 + "px");
    root2.style.setProperty("--grid-pad-x", PAD2 + "px");
    root2.style.setProperty("--grid-pad-y", PAD2 + "px");
  }
  function enterEditMode() {
    editing4 = true;
    editSnapshot = cloneLayout(layout3);
    el("dash-grid-root")?.classList.add("dashboard--editing");
    const editBtn = el("dashEditBtn"), controls = el("dashEditControls");
    if (editBtn) editBtn.style.display = "none";
    if (controls) controls.style.display = "flex";
    updateGridOverlay();
  }
  function exitEditMode(doSave) {
    editing4 = false;
    if (doSave) {
      saveLayout(layout3);
    } else {
      layout3 = editSnapshot;
      applyLayout(layout3);
    }
    el("dash-grid-root")?.classList.remove("dashboard--editing");
    const editBtn = el("dashEditBtn"), controls = el("dashEditControls");
    if (editBtn) editBtn.style.display = "flex";
    if (controls) controls.style.display = "none";
    closeAddPanel();
  }
  function othersWant(room, exceptId) {
    return layout3.some((x) => x.id !== exceptId && x.visible && rooms[x.id] === room);
  }
  function removeCard(id) {
    const c = getCard(id);
    if (c) c.visible = false;
    applyLayout(layout3);
    renderAddPanel();
    const room = rooms[id];
    if (room && dashActive() && !othersWant(room, id)) notifyRoom2("dashcard:room:blur", room);
  }
  function addCard(id) {
    const c = getCard(id);
    if (!c) return;
    const defW = c.w || 3, defH = c.h || 2;
    const slot = findFreeSlot(layout3, defW, defH);
    c.x = slot.x;
    c.y = slot.y;
    c.w = defW;
    c.h = defH;
    c.visible = true;
    applyLayout(layout3);
    renderAddPanel();
    const room = rooms[id];
    if (room && dashActive() && !othersWant(room, id)) notifyRoom2("dashcard:room:focus", room);
  }
  function renderAddPanel() {
    const panel = el("dashAddPanel");
    if (!panel) return;
    panel.innerHTML = "";
    const hdr = document.createElement("div");
    hdr.className = "dash-add-header";
    hdr.textContent = "Hidden Cards";
    panel.appendChild(hdr);
    const hidden = layout3.filter((c) => !c.visible);
    if (hidden.length === 0) {
      const empty = document.createElement("div");
      empty.className = "dash-add-empty";
      empty.textContent = "All cards are visible";
      panel.appendChild(empty);
    } else {
      const chips = document.createElement("div");
      chips.className = "dash-add-chips";
      for (const c of hidden) {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "chip";
        chip.innerHTML = "<span>+</span>" + (CARD_LABELS[c.id] || c.id);
        chip.addEventListener("click", () => addCard(c.id));
        chips.appendChild(chip);
      }
      panel.appendChild(chips);
    }
    const resetLink = document.createElement("a");
    resetLink.className = "dash-reset-link";
    resetLink.href = "#";
    resetLink.textContent = "Reset to default layout";
    resetLink.addEventListener("click", (e) => {
      e.preventDefault();
      layout3 = cloneLayout(DEFAULT_LAYOUT);
      applyLayout(layout3);
      closeAddPanel();
    });
    panel.appendChild(resetLink);
  }
  function openAddPanel() {
    renderAddPanel();
    el("dashAddPanel")?.classList.add("open");
  }
  function closeAddPanel() {
    el("dashAddPanel")?.classList.remove("open");
  }
  return {
    getLayout: () => layout3,
    setLayout: (l) => {
      layout3 = l;
    },
    isEditing: () => editing4,
    enterEditMode,
    exitEditMode,
    addCard,
    removeCard,
    renderAddPanel,
    openAddPanel,
    closeAddPanel,
    updateGridOverlay
  };
}

